from pathlib import Path
import tempfile
import tracemalloc
import unittest

import pytest

from tools.logs import peak_trc_audit


TRACE = """;$FILEVERSION=1.1
;$STARTTIME=46250.0
;
; Start time: 16.08.2026 20:00:00.000.0
; Generated by PCAN-View v5.3
     1)         0.0  Rx         0160  8  00 01 02 03 04 05 06 07
     2)        10.0  Rx         0160  8  00 01 02 03 04 05 06 08
     3)        20.0  Tx         06F0  3  AA BB CC
     4)        30.0  Rx         0160  8  00 01 02 03 04 05 06 08
"""


class PeakTrcAuditTest(unittest.TestCase):
    def load(self, text=TRACE):
        directory = tempfile.TemporaryDirectory()
        self.addCleanup(directory.cleanup)
        path = Path(directory.name) / "capture.trc"
        path.write_text(text, encoding="ascii")
        return peak_trc_audit.load_trace(path)

    def test_parser_and_identifier_statistics(self):
        trace = self.load()
        audit = peak_trc_audit.audit_trace(
            trace, candidate_id=0x6F0, bitrate=500_000
        )
        self.assertEqual(trace.file_version, "1.1")
        self.assertEqual(trace.frames[2].data, bytes.fromhex("AABBCC"))
        self.assertEqual(audit.frame_count, 4)
        self.assertEqual(audit.rx_count, 3)
        self.assertEqual(audit.tx_count, 1)
        self.assertEqual(audit.candidate_count, 1)
        by_id = {item.can_id: item for item in audit.identifiers}
        self.assertEqual(by_id[0x160].dlcs, (8,))
        self.assertEqual(by_id[0x160].median_period_ms, 15)
        self.assertEqual(by_id[0x160].maximum_period_ms, 20)
        self.assertEqual(by_id[0x160].unique_payloads, 2)
        self.assertGreater(audit.load.average_max_percent, 0)

    def test_classical_can_bit_bounds(self):
        standard = peak_trc_audit.Frame(1, 0, "Rx", 0x160, bytes(8))
        extended = peak_trc_audit.Frame(
            1, 0, "Rx", 0x18DAF110, bytes(8), True
        )
        self.assertEqual(
            peak_trc_audit.frame_bit_bounds(standard), (111, 135)
        )
        self.assertEqual(
            peak_trc_audit.frame_bit_bounds(extended), (131, 160)
        )

    def test_eight_digit_low_numeric_id_remains_extended(self):
        trace = self.load(TRACE.replace("0160", "00000160"))
        extended = [frame for frame in trace.frames if frame.can_id == 0x160]
        self.assertTrue(extended)
        self.assertTrue(all(frame.extended for frame in extended))

    def test_rtr_warning_and_error_rows_are_counted(self):
        text = TRACE.replace(
            "     3)        20.0  Tx         06F0  3  AA BB CC\n",
            "     3)        20.0  Tx         06F0  8  RTR\n",
        ).replace(
            "     4)        30.0  Rx         0160  8  00 01 02 03 04 05 06 08\n",
            "     4)        25.0  Warng  FFFFFFFF  4  00 00 00 04  BUSLIGHT\n"
            "     5)        27.0  Error      0008  4  00 19 08 08\n"
            "     6)        30.0  Rx         0160  8  00 01 02 03 04 05 06 08\n",
        )
        trace = self.load(text)
        audit = peak_trc_audit.audit_trace(trace, bitrate=500_000)
        self.assertEqual(audit.remote_count, 1)
        self.assertEqual(audit.warning_count, 1)
        self.assertEqual(audit.error_count, 1)
        remote = [frame for frame in trace.frames if frame.remote][0]
        self.assertEqual(remote.dlc, 8)
        self.assertEqual(
            peak_trc_audit.frame_bit_bounds(remote), (47, 55)
        )

    def test_bad_dlc_number_and_timestamp_are_rejected(self):
        cases = {
            "dlc": TRACE.replace("06F0  3  AA BB CC", "06F0  4  AA BB CC"),
            "number": TRACE.replace("     3)", "     8)"),
            "timestamp": TRACE.replace("        20.0", "         5.0"),
        }
        for name, text in cases.items():
            with self.subTest(name=name), self.assertRaises(
                peak_trc_audit.TraceError
            ):
                self.load(text)

    def test_unknown_version_and_unsupported_row_are_rejected(self):
        for text in (
            TRACE.replace("FILEVERSION=1.1", "FILEVERSION=2.0"),
            TRACE + "unsupported row\n",
        ):
            with self.assertRaises(peak_trc_audit.TraceError):
                self.load(text)

    def write(self, content):
        directory = tempfile.TemporaryDirectory()
        self.addCleanup(directory.cleanup)
        path = Path(directory.name) / "capture.trc"
        path.write_bytes(content)
        return path

    def test_cp1251_header_comment_is_accepted(self):
        text = TRACE.replace(
            "; Generated by PCAN-View v5.3\n",
            "; Generated by PCAN-View v5.3 (\u0440\u0443\u0441\u0441\u043a\u0438\u0439)\n"
            "; \u0417\u0430\u043f\u0438\u0441\u044c: \u043f\u0440\u043e\u0433\u0440\u0435\u0432\n",
        )
        trace = peak_trc_audit.load_trace(self.write(text.encode("cp1251")))
        self.assertEqual(
            trace.generator,
            "PCAN-View v5.3 (\u0440\u0443\u0441\u0441\u043a\u0438\u0439)",
        )
        self.assertEqual(len(trace.frames), 4)

    def test_record_row_must_be_ascii(self):
        text = TRACE.encode("ascii").replace(b"AA BB CC", b"AA BB C\xc1")
        with self.assertRaisesRegex(
            peak_trc_audit.TraceError, r"capture.trc:8: record row is not ASCII"
        ):
            peak_trc_audit.load_trace(self.write(text))

    def test_header_reads_without_records_and_records_stream_in_order(self):
        path = self.write((TRACE + "unsupported row\n").encode("ascii"))
        header = peak_trc_audit.read_header(path)
        self.assertEqual(header.file_version, "1.1")
        self.assertEqual(header.start_time, "46250.0")
        records = peak_trc_audit.iter_records(path)
        numbers = [next(records).number for _ in range(4)]
        self.assertEqual(numbers, [1, 2, 3, 4])
        with self.assertRaisesRegex(
            peak_trc_audit.TraceError, "capture.trc:10: unsupported TRC row"
        ):
            next(records)

    @pytest.mark.slow
    def test_streaming_memory_does_not_grow_with_the_capture(self):
        peaks = []
        for count in (20_000, 200_000):
            rows = "".join(
                f"{number:7d}) {number * 0.1:12.1f}  Rx         0160  8  "
                "00 01 02 03 04 05 06 07\n"
                for number in range(1, count + 1)
            )
            path = self.write((TRACE.split("     1)")[0] + rows).encode("ascii"))
            tracemalloc.start()
            try:
                frames = sum(1 for _record in peak_trc_audit.iter_records(path))
                peaks.append(tracemalloc.get_traced_memory()[1])
            finally:
                tracemalloc.stop()
            self.assertEqual(frames, count)
        self.assertLess(peaks[1], 256 * 1024)
        self.assertLess(peaks[1], peaks[0] + 16 * 1024)


if __name__ == "__main__":
    unittest.main()
